import pandas as pd
import numpy as np

def find_total_duration_and_concurrent_tasks(tasks: pd.DataFrame) -> pd.DataFrame:
    if tasks.empty:
        return pd.DataFrame(columns=['employee_id', 'total_task_hours', 'max_concurrent_tasks'])

    tasks['start_time'] = pd.to_datetime(tasks['start_time'])
    tasks['end_time'] = pd.to_datetime(tasks['end_time'])

    results = []
    for emp_id, group in tasks.groupby('employee_id'):
        times = sorted(list(set(group['start_time']).union(set(group['end_time']))))
        total_seconds = 0
        max_concurrent = 0
        for i in range(len(times) - 1):
            st, et = times[i], times[i + 1]
            active = group[(group['start_time'] <= st) & (group['end_time'] >= et)]
            cnt = len(active)
            if cnt > 0:
                total_seconds += (et - st).total_seconds()
                max_concurrent = max(max_concurrent, cnt)
        results.append({
            'employee_id': emp_id,
            'total_task_hours': int(np.floor(total_seconds / 3600)),
            'max_concurrent_tasks': max_concurrent
        })

    res_df = pd.DataFrame(results)
    return res_df.sort_values(by='employee_id').reset_index(drop=True)
